sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float magnitude;
uniform float frequency;
uniform float width;
uniform float phase;
uniform float offset;
layout(color) uniform half4 color;
uniform float punch;
uniform float smoothing;
layout(color) uniform half4 tint;
uniform float tintAmount;
uniform float angle;
float hash(float x) { return fract(sin(x * 127.1 + 311.7) * 43758.5453) * 2.0 - 1.0; }
float wobble(float x) {
    float i = floor(x);
    float t = x - i;
    float a = hash(i) * t;
    float b = hash(i + 1.0) * (t - 1.0);
    return mix(a, b, t * t * (3.0 - 2.0 * t)) * 2.2;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return half4(0.0);
    float ra = radians(angle);
    float2 ax = float2(cos(ra), sin(ra));
    float2 ay = float2(-ax.y, ax.x);
    float span = max(abs(dot(size, abs(ax))), 1.0);
    float tall = max(abs(dot(size, abs(ay))), 1.0);
    float2 r = float2(dot(coord - size * 0.5, ax), dot(coord - size * 0.5, ay));
    float x = r.x / span + 0.5;
    float f = max(frequency, 0.1);
    float centre = (clamp(wobble(x * f + phase), -1.0, 1.0) * magnitude + offset) * tall * 0.5;
    float d = 0.5 / span;
    float slope = (wobble((x + d) * f + phase) - wobble((x - d) * f + phase)) / (2.0 * d) * magnitude * tall * 0.5 / span;
    float turn = wobble(x * f * 0.5 + phase * 0.7 + 17.3);
    float halfWidth = max(width, 0.0) * tall * 0.06 * abs(turn) + 0.25;
    float off = abs(r.y - centre) / sqrt(1.0 + slope * slope);
    float soft = 0.75 + max(smoothing, 0.0) * tall * 0.1;
    float cover = (1.0 - smoothstep(halfWidth - soft, halfWidth + soft, off)) * float(src.a);
    if (punch > 0.5) return src * half(1.0 - cover);
    half3 rgb = turn < 0.0 ? half3(mix(float3(color.rgb), float3(tint.rgb), clamp(tintAmount, 0.0, 1.0))) : color.rgb;
    float a = cover * float(color.a);
    return half4(rgb * half(a), half(a)) + src * half(1.0 - a);
}
